INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT128-S2-Q5$batch08$, 128, 2, 5, $batch08$Most Supported$batch08$, $batch08$Human Resources Director: Some people dislike their jobs but still go to work every day because they feel that it is ethically wrong to miss work. Others enjoy their jobs but sometimes miss work because they genuinely believe that they are too sick to work or that they might infect others if they go to work. This makes it difficult to _______.$batch08$, $batch08$Which one of the following most reasonably completes the argument?$batch08$, $batch08$C$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=128 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT128-S2-Q5$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$determine whether employees absent from work more often than others are any less fearful of losing their jobs$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT128-S2-Q5$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$maintain accurate absenteeism records for all the different employees of a company$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT128-S2-Q5$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$draw any conclusions about an employee's job satisfaction from his or her absenteeism record$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT128-S2-Q5$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$assess the trustworthiness of employees who claim that they must miss work because they are ill$batch08$, $batch08$Opposite$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT128-S2-Q5$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$make any reliable predictions about an employee's future behavior from his or her absenteeism record$batch08$, $batch08$Too Strong$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT128-S2-Q5$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT128-S2-Q5$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Some people dislike their jobs but never miss work, because missing work feels wrong. Others like their jobs but sometimes miss work because they're really sick or don't want to infect anyone.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Pause and infer. The two groups are set up as opposites: the unhappy worker with a perfect record and the happy worker who misses days. So attendance doesn't line up with how much people like their jobs.$batch08$), (2, $batch08$Goal$batch08$, $batch08$You can't read job satisfaction off an absence record.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT128-S2-Q5$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$Fear of losing one's job never comes up.$batch08$), ($batch08$B$batch08$, $batch08$Nothing suggests the records themselves are inaccurate.$batch08$), ($batch08$C$batch08$, $batch08$Unhappy workers who never miss and happy workers who sometimes do: absences don't tell you who likes the job.$batch08$), ($batch08$D$batch08$, $batch08$The passage says these workers "genuinely believe" they're too sick. Their honesty isn't in question.$batch08$), ($batch08$E$batch08$, $batch08$The passage is about one thing, job satisfaction. It doesn't show that absence records predict nothing about future behavior.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT128-S2-Q5$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
